/// <summary>
/// PaffH 24.02.24
/// </summary>
/// <param name="_parameters">NDXAssistProActionsParameters</param>
[SubscribesTo(tableStr(NDXAssistProActions), staticDelegateStr(NDXAssistProActions, onUpdatingNDXAssistProActions))]
public static void NDXAssistProActions_onUpdatingNDXAssistProActions(NDXAssistProActionsParameters _parameters)
{       
    NDX_KBV2RicoKalkMap nDX_KBV2RicoKalkMap = NDX_KBV2RicoKalkMap::findRicoKalkBVNr(any2int(_parameters.nDXAssistProActivitiesMap.AssistProProjectNumber));
    KCS_KBVBuildingProjectTable kcs_KBVBuildingProjectTable = kcs_KBVBuildingProjectTable::find(ndx_KBV2RicoKalkMap.KBVBuildingProjectID);
    if(kcs_KBVBuildingProjectTable)
    {
        smmActivityParentLinkTable smmActivityParentLinkTableBV = smmActivityParentLinkTable::updateOrCreateLink(_parameters.smmActivities.ActivityNumber, smmActivityParentType::BuildingProject, kcs_KBVBuildingProjectTable.RecId);

        // Falls eine primäre Verknüpfung zum Bauvorhaben besteht, diese löschen
        if (smmActivityParentLinkTableBV && smmActivityParentLinkTableBV.PrimaryLink == NoYes::Yes)
        {
            smmActivityParentLinkTableBV.selectForUpdate(true);
            smmActivityParentLinkTableBV.PrimaryLink = NoYes::No;
            ttsbegin;
            smmActivityParentLinkTableBV.update();
            ttscommit;
        }
    }
}
